function transform(ctx) {
  var MAP = {};
  var suffix = "";
  var isp = (ctx.isp || "").trim();
  if (isp) { suffix = MAP[isp] !== undefined ? MAP[isp] : (isp.charAt(0) === "@" ? isp : ""); }
  var full = (ctx.username || "") + suffix;
  return { full_username: full, encoded_username: url_encode(full), callback: "sdu", ts: Math.floor(now_ms() / 1000) };
}

function transform(ctx) {
  var acId = "12"; // 原仓库 config.json/new_from_user 默认 acid=12
  var n = "200";
  var type = "1";
  var ip = ctx.local_ip;
  if (!ip) throw new Error("无法获取本机 IP，请确认已连接校园网");
  var token = ctx.vars.challenge;
  var full = ctx.vars.full_username || (ctx.username || "");
  var info = srun_info(JSON.stringify({ acid: Number(acId), enc_ver: "srun_bx1", ip: ip, password: ctx.password, username: full }), token);
    var hmd5 = hmac_md5(token, ctx.password);
  var checksum = sha1(token + full + token + hmd5 + token + acId + token + ip + token + n + token + type + token + info);
  return { encoded_username: url_encode(full), encoded_password: url_encode("{MD5}" + hmd5), encoded_info: url_encode(info), checksum: checksum, ac_id: acId, n: n, protocol_type: type, login_ip: ip };
}
